#!/usr/bin/env bash
# Prepares a lab VM: waits for cloud-init, makes sure ublk is available, installs Rust.

log "waiting for cloud-init"
cloud-init status --wait >/dev/null 2>&1 || log "cloud-init reported errors; continuing ($(cloud-init status 2>&1 | tail -1))"

missing=()
# libclang-dev: libublk's bindings are generated by bindgen at build time. bpftrace: bench-reads
# finds where a volume's data is on the disk.
for pkg in build-essential pkg-config fio jq netcat-openbsd rsync curl clang libclang-dev iperf3 bpftrace; do
    dpkg -s "$pkg" >/dev/null 2>&1 || missing+=("$pkg")
done
if ((${#missing[@]})); then
    log "installing ${missing[*]}"
    sudo apt-get update -qq
    sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "${missing[@]}" >/dev/null
fi

if ! sudo modprobe ublk_drv 2>/dev/null; then
    log "ublk_drv not in the base kernel modules; installing linux-modules-extra"
    sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "linux-modules-extra-$(uname -r)" >/dev/null
    sudo modprobe ublk_drv
fi

if [[ ! -x $HOME/.cargo/bin/cargo ]]; then
    log "installing Rust (stable, minimal)"
    curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh -s -- -y --profile minimal --default-toolchain stable >/dev/null
fi

# Guest kernel arguments (GUEST_KERNEL_ARGS from lab.conf). Applied through a GRUB drop-in;
# a reboot is needed when they are not active yet.
wanted=${GUEST_KERNEL_ARGS:-}
dropin=/etc/default/grub.d/90-flaminio-lab.cfg
if [[ -n $wanted ]]; then
    line="GRUB_CMDLINE_LINUX_DEFAULT=\"\$GRUB_CMDLINE_LINUX_DEFAULT $wanted\""
    if [[ $(cat "$dropin" 2>/dev/null) != "$line" ]]; then
        log "setting guest kernel arguments: $wanted"
        echo "$line" | sudo tee "$dropin" >/dev/null
        sudo update-grub >/dev/null 2>&1
    fi
elif [[ -f $dropin ]]; then
    sudo rm -f "$dropin"
    sudo update-grub >/dev/null 2>&1
fi
missing_args=""
for arg in $wanted; do
    grep -qw -- "$arg" /proc/cmdline || missing_args+=" $arg"
done

disk=$(data_disk)
cat <<SUMMARY
  kernel     $(uname -r)
  cpus       $(nproc)
  memory     $(free -g | awk '/Mem:/ {print $2}') GiB
  ublk       $(test -e /dev/ublk-control && echo "ready (/dev/ublk-control)" || echo MISSING)
  io_uring   $(sysctl -n kernel.io_uring_disabled 2>/dev/null | sed 's/^0$/enabled/;s/^[12]$/DISABLED/')
  rust       $(cargo --version)
  fio        $(fio --version)
  data disk  $disk $(lsblk -dn -o SIZE "$disk") (rotational=$(lsblk -dn -o ROTA "$disk"))
  kernel args $(if [[ -z $wanted ]]; then echo "(none)"; elif [[ -z $missing_args ]]; then echo "active: $wanted"; else echo "PENDING REBOOT:$missing_args"; fi)
  cet        $(grep -qw user_shstk /proc/cpuinfo && echo "user shadow stacks available" || echo "user shadow stacks off")
SUMMARY
if [[ -n $missing_args ]]; then
    echo "REBOOT_REQUIRED"
fi
